/* @lc app=leetcode id=3459 lang=kotlin */ class Solution { fun g(gr: Array<IntArray>, memo: IntArray, i: Int, j: Int, d: Int, t: Int): Int = (((i * gr[0].size + j) * 4 + d) * 2 + t).let { key -> if (memo[key] != 0) memo[key] else (if (gr[i][j] == 2) 0 else 2).let { exp -> listOf(d to t, (d + 1) % 4 to 1).filterIndexed { idx, _ -> idx == 0 || t == 0 }.maxOf { (dd, tt) -> intArrayOf(1, 1, -1, -1)[dd].let { dx -> intArrayOf(1, -1, -1, 1)[dd].let { dy -> if (i + dx in gr.indices && j + dy in gr[0].indices && gr[i + dx][j + dy] == exp) g(gr, memo, i + dx, j + dy, dd, tt) else 0 } } }.let { 1 + it }.also { memo[key] = it } } } fun lenOfVDiagonal(grid: Array<IntArray>): Int = IntArray(grid.size * grid[0].size * 8).let { memo -> grid.indices.maxOf { i -> grid[0].indices.maxOfOrNull { j -> if (grid[i][j] == 1) (0..3).maxOf { d -> g(grid, memo, i, j, d, 0) } else 0 } ?: 0 } } }